const $ = (selector, root = document) => root.querySelector(selector);
const $$ = (selector, root = document) => [...root.querySelectorAll(selector)];

const initialScenes = [
  { title: 'A luz certa muda tudo', narration: 'Antes de qualquer equipamento, existe uma escolha que transforma a cena: a luz.', visual: 'Sala comum recebendo um facho de luz lateral, atmosfera cinematográfica', duration: 8 },
  { title: 'Comece pela direção', narration: 'Observe de onde a luz vem. Gire o objeto até encontrar o ângulo que revela sua textura.', visual: 'Mão ajustando uma luminária, sombras longas e quentes na parede', duration: 8 },
  { title: 'Deixe espaço para respirar', narration: 'Depois, reduza o excesso. Uma sombra bem colocada dá profundidade e deixa a imagem respirar.', visual: 'Composição minimalista, metade iluminada e metade em sombra azul', duration: 7 },
  { title: 'O detalhe vira memória', narration: 'É assim que uma sala deixa de ser apenas um lugar e vira uma cena que fica.', visual: 'Plano final acolhedor, luz suave, sensação de conclusão', duration: 7 }
];

const state = { id: null, name: 'Sem título', topic: $('#topic').value, duration: 30, style: 'Cinematográfico', format: 'vertical', voice: 'Aoede', mode: 'animated', scenes: [], selected: 0, assets: [], volume: 85, music: 18 };
let objectUrls = [];
let authSession = JSON.parse(localStorage.getItem('cena-auth') || 'null');
let hostedConfig = null;

async function apiFetch(url, options = {}) { const headers = new Headers(options.headers || {}); if (authSession?.access_token) headers.set('Authorization', `Bearer ${authSession.access_token}`); return fetch(url, { ...options, headers }); }
async function bootstrapAuth() { if (!window.CENA_HOSTED) return; try { hostedConfig = await (await fetch('/api/config')).json(); } catch { return; } if (!hostedConfig.url || !hostedConfig.publishableKey || localStorage.getItem('cena-local-only') === '1') return; if (!authSession) $('#authGate').hidden = false; else setStatus('conectado ao Supabase'); }
async function submitAuth(mode) { if (!hostedConfig?.url || !hostedConfig?.publishableKey) return setAuthMessage('Configure SUPABASE_URL e SUPABASE_PUBLISHABLE_KEY na Vercel.'); const email = $('#authEmail').value.trim(); const password = $('#authPassword').value; if (!email || password.length < 6) return setAuthMessage('Informe um e-mail e uma senha com pelo menos 6 caracteres.'); const endpoint = mode === 'signup' ? '/auth/v1/signup' : '/auth/v1/token?grant_type=password'; try { const response = await fetch(`${hostedConfig.url}${endpoint}`, { method: 'POST', headers: { apikey: hostedConfig.publishableKey, 'content-type': 'application/json' }, body: JSON.stringify({ email, password }) }); const data = await response.json(); if (!response.ok) throw new Error(data.msg || data.error_description || 'Não foi possível autenticar.'); if (!data.access_token) return setAuthMessage('Conta criada. Confirme o e-mail recebido e depois entre.'); authSession = data; localStorage.setItem('cena-auth', JSON.stringify(authSession)); $('#authGate').hidden = true; setStatus('conectado ao Supabase'); toast('Acesso confirmado.', 'success'); } catch (error) { setAuthMessage(error.message); } }
function setAuthMessage(message) { $('#authMessage').textContent = message; }

function toast(message, kind = '') { const node = document.createElement('div'); node.className = `toast ${kind}`; node.textContent = message; $('#toastStack').appendChild(node); setTimeout(() => node.remove(), 4200); }
function setStatus(message) { $('#projectStatus').textContent = `· ${message}`; }
function formatTime(seconds) { return `00:${String(Math.round(seconds)).padStart(2, '0')}`; }
function totalDuration() { return state.scenes.reduce((sum, scene) => sum + Number(scene.duration || 0), 0); }
function currentScene() { return state.scenes[state.selected] || null; }

function setProgress(percent, title, step = 'brief') { $('#progressPanel').classList.add('visible'); $('#progressBar').style.width = `${percent}%`; $('#progressPercent').textContent = `${percent}%`; $('#progressTitle').textContent = title; $$('.progress-steps span').forEach((el) => el.classList.toggle('done', el.dataset.step === step || ['brief', 'script', 'voice', 'render'].indexOf(el.dataset.step) < ['brief', 'script', 'voice', 'render'].indexOf(step))); }

function renderScenes() {
  const timeline = $('#timeline'); $('#sceneCount').textContent = `${state.scenes.length} ${state.scenes.length === 1 ? 'cena' : 'cenas'}`;
  if (!state.scenes.length) { timeline.innerHTML = '<div class="empty-state"><span class="empty-icon">✦</span><h3>Sua sequência começa aqui</h3><p>Gere um roteiro ou adicione uma cena manualmente.</p><button class="small-button" id="emptyAddBtn">Adicionar primeira cena</button></div>'; $('#emptyAddBtn').onclick = addScene; updatePreview(); return; }
  timeline.innerHTML = state.scenes.map((scene, index) => `<article class="scene-card ${index === state.selected ? 'selected' : ''}" data-index="${index}"><div class="scene-index">${String(index + 1).padStart(2, '0')}</div><div class="scene-thumb"><span class="thumb-label">${String(scene.duration).padStart(2, '0')}s</span>${scene.image ? `<img src="${scene.image}" alt="" />` : ''}</div><div class="scene-copy"><input class="scene-title-input" data-field="title" value="${escapeHtml(scene.title)}" aria-label="Título da cena ${index + 1}" /><textarea class="scene-narration-input" data-field="narration" rows="2" aria-label="Narração da cena ${index + 1}">${escapeHtml(scene.narration)}</textarea><textarea class="scene-visual-input" data-field="visual" rows="1" aria-label="Visual da cena ${index + 1}">${escapeHtml(scene.visual)}</textarea></div><div class="scene-time"><input class="scene-duration" type="number" min="1" max="60" value="${scene.duration}" aria-label="Duração da cena ${index + 1}" />s</div><div class="scene-actions"><button data-action="up" title="Mover para cima">↑</button><button data-action="down" title="Mover para baixo">↓</button><button data-action="delete" title="Excluir cena">×</button></div></article>`).join('');
  $$('.scene-card').forEach((card) => { const index = Number(card.dataset.index); card.onclick = (event) => { if (event.target.closest('button,input,textarea')) return; state.selected = index; renderScenes(); }; $$('.scene-title-input,.scene-narration-input,.scene-visual-input,.scene-duration', card).forEach((input) => input.oninput = () => { const field = input.dataset.field || 'duration'; state.scenes[index][field] = field === 'duration' ? Math.max(1, Number(input.value)) : input.value; state.selected = index; updatePreview(); setStatus('alterações pendentes'); }); $$('.scene-actions button', card).forEach((button) => button.onclick = () => sceneAction(button.dataset.action, index)); }); updatePreview();
}

function escapeHtml(value = '') { return String(value).replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;').replaceAll('"', '&quot;'); }
function sceneAction(action, index) { if (action === 'delete') state.scenes.splice(index, 1); if (action === 'up' && index > 0) [state.scenes[index - 1], state.scenes[index]] = [state.scenes[index], state.scenes[index - 1]]; if (action === 'down' && index < state.scenes.length - 1) [state.scenes[index + 1], state.scenes[index]] = [state.scenes[index], state.scenes[index + 1]]; state.selected = Math.min(state.selected, Math.max(0, state.scenes.length - 1)); renderScenes(); setStatus('alterações pendentes'); }
function addScene() { state.scenes.push({ title: 'Nova cena', narration: 'Escreva a narração desta cena.', visual: 'Descreva o que deve aparecer na imagem.', duration: 5 }); state.selected = state.scenes.length - 1; renderScenes(); setStatus('alterações pendentes'); }

function updatePreview() { const scene = currentScene(); $('#frameNumber').textContent = scene ? String(state.selected + 1).padStart(2, '0') : '01'; $('#frameTitle').innerHTML = scene ? escapeHtml(scene.title).replace(/\s([^\s]+)$/, '<br /><em>$1</em>') : 'A luz certa<br /><em>muda tudo.</em>'; $('#frameCaption').textContent = scene ? scene.visual : 'Prévia da primeira cena'; $('#frameDuration').textContent = formatTime(totalDuration() || Number($('#duration').value)); $('#formatBadge').textContent = state.format === 'vertical' ? '9:16' : state.format === 'square' ? '1:1' : '16:9'; $('#previewHint').textContent = scene ? `${scene.duration}s · cena ${state.selected + 1} de ${state.scenes.length}` : 'Selecione uma cena para editar'; }

async function generateScript() { const topic = $('#topic').value.trim(); if (!topic) return toast('Escreva um tema antes de gerar o roteiro.', 'error'); state.topic = topic; state.duration = Number($('#duration').value); state.style = $('#style').value; setProgress(18, 'Organizando o briefing…', 'script'); $('#generateBtn').disabled = true; $('#generateBtn').innerHTML = '<span class="spark">◌</span> Gerando roteiro…'; try { const response = await apiFetch('/api/generate-script', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ topic, duration: state.duration, style: state.style, format: state.format }) }); if (!response.ok) throw await response.json(); const data = await response.json(); state.name = data.title || topic.slice(0, 34); state.scenes = (data.scenes || []).map((scene) => ({ ...scene, duration: Number(scene.duration) || 5 })); toast('Roteiro gerado pelo Gemini.', 'success'); setProgress(53, 'Roteiro pronto para revisão', 'script'); } catch (error) { state.name = topic.slice(0, 34); state.scenes = makeLocalScenes(topic, state.duration); toast(error?.error ? `${error.error} Usando rascunho local.` : 'Gemini indisponível. Usando rascunho local.', 'error'); setProgress(42, 'Rascunho local pronto — revise as cenas', 'script'); } finally { $('#projectName').textContent = state.name; $('#generateBtn').disabled = false; $('#generateBtn').innerHTML = '<span class="spark">✦</span> Gerar roteiro <span class="button-arrow">↗</span>'; renderScenes(); setStatus('roteiro gerado'); } }
function makeLocalScenes(topic, duration) { const chunks = [
  ['A pergunta certa', `Tudo começa com uma pergunta: o que realmente importa quando falamos de ${topic}?`, `Abertura cinematográfica sobre ${topic}, luz lateral e textura rica`],
  ['Olhe de outro jeito', 'Quando mudamos o ângulo, detalhes que passavam despercebidos ganham espaço.', `Close em detalhes relacionados a ${topic}, movimento lento e composição editorial`],
  ['O detalhe permanece', 'No fim, é a soma dessas pequenas escolhas que transforma uma ideia em experiência.', `Plano final memorável sobre ${topic}, atmosfera acolhedora e acabamento de campanha`]
]; const each = Math.floor(duration / chunks.length); return chunks.map((item, index) => ({ title: item[0], narration: item[1], visual: item[2], duration: index === chunks.length - 1 ? duration - each * (chunks.length - 1) : each })); }

async function saveProject() { state.topic = $('#topic').value; state.duration = Number($('#duration').value); state.style = $('#style').value; state.voice = $('#voice').value; const payload = { ...state, name: state.name || 'Sem título', createdAt: state.createdAt || new Date().toISOString() }; try { const res = await apiFetch('/api/projects', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(payload) }); const data = await res.json(); if (!res.ok) throw data; state.id = data.id; localStorage.setItem('cena-project', JSON.stringify(state)); toast('Projeto salvo no Supabase.', 'success'); setStatus('salvo na nuvem'); } catch { state.id ||= crypto.randomUUID(); localStorage.setItem('cena-project', JSON.stringify(state)); toast('Projeto salvo neste navegador.', 'success'); setStatus('salvo neste navegador'); } }
async function loadProjects() { const grid = $('#libraryGrid'); let projects = []; try { const response = await apiFetch('/api/projects'); if (!response.ok) throw new Error(); projects = await response.json(); } catch { const saved = localStorage.getItem('cena-project'); if (saved) projects = [{ payload: JSON.parse(saved), updated_at: JSON.parse(saved).updatedAt }]; } if (!projects.length) { grid.innerHTML = '<div class="empty-state"><span class="empty-icon">⌁</span><h3>Nenhum projeto ainda</h3><p>Salve um projeto para ele aparecer aqui.</p></div>'; return; } grid.innerHTML = projects.map((item) => { const p = item.payload || item; return `<article class="library-card"><div class="lib-preview">${escapeHtml(p.name || 'Sem título')}</div><h3>${escapeHtml(p.name || 'Sem título')}</h3><p>${p.scenes?.length || 0} cenas · ${p.duration || 30}s · ${p.format === 'vertical' ? '9:16' : p.format}</p><button data-open="${p.id || ''}">Abrir projeto ↗</button></article>` }).join(''); $$('[data-open]').forEach((button) => button.onclick = () => openProject(button.dataset.open)); }
async function openProject(id) { try { const res = await apiFetch(`/api/projects/${id}`); if (!res.ok) throw new Error(); hydrate(await res.json()); } catch { const saved = localStorage.getItem('cena-project'); if (saved) hydrate(JSON.parse(saved)); } showView('editor'); toast('Projeto reaberto.', 'success'); }
function hydrate(data) { Object.assign(state, data); $('#topic').value = state.topic || ''; $('#duration').value = state.duration || 30; $('#style').value = state.style || 'Cinematográfico'; $('#voice').value = state.voice || 'Aoede'; $('#projectName').textContent = state.name || 'Sem título'; $$('.format-option').forEach((el) => el.classList.toggle('selected', el.dataset.format === state.format)); $$('.mode').forEach((el) => el.classList.toggle('selected', el.dataset.mode === state.mode)); renderScenes(); }

function makeSrt() { if (!state.scenes.length) return toast('Gere ou adicione cenas antes de baixar legendas.', 'error'); let cursor = 0; const lines = state.scenes.map((scene, i) => { const start = srtTime(cursor); cursor += Number(scene.duration); return `${i + 1}\n${start} --> ${srtTime(cursor)}\n${scene.narration}\n`; }).join('\n'); downloadBlob(lines, `${slug(state.name)}.srt`, 'application/x-subrip'); toast('SRT exportado com os tempos das cenas. Para alinhamento palavra a palavra, use whisper.cpp.', 'success'); }
function srtTime(seconds) { const ms = Math.round((seconds % 1) * 1000); const total = Math.floor(seconds); return `00:${String(Math.floor(total / 60)).padStart(2, '0')}:${String(total % 60).padStart(2, '0')},${String(ms).padStart(3, '0')}`; }
function slug(value) { return (value || 'cena').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, ''); }
function downloadBlob(content, name, type) { const blob = content instanceof Blob ? content : new Blob([content], { type }); const link = document.createElement('a'); link.href = URL.createObjectURL(blob); link.download = name; link.click(); setTimeout(() => URL.revokeObjectURL(link.href), 500); }
function exportProject() { downloadBlob(JSON.stringify({ ...state, assets: state.assets.map(({ name, type }) => ({ name, type })) }, null, 2), `${slug(state.name)}.json`, 'application/json'); }

async function renderVideo() { if (!state.scenes.length) return toast('Adicione cenas antes de renderizar.', 'error'); setProgress(66, 'Preparando renderização…', 'render'); try { const response = await apiFetch('/api/render', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ projectId: state.id, duration: totalDuration(), format: state.format, scenes: state.scenes }) }); if (!response.ok) throw new Error(); const job = await response.json(); toast('Renderização enfileirada. Inicie `npm run worker` em outro terminal.', 'success'); pollJob(job.id); } catch { await renderBrowserVideo(); } }
async function renderBrowserVideo() { if (!window.MediaRecorder) return toast('Este navegador não suporta renderização local. Use o worker FFmpeg.', 'error'); const scene = currentScene() || state.scenes[0]; const canvas = document.createElement('canvas'); const ratio = state.format === 'square' ? [720, 720] : state.format === 'horizontal' ? [1280, 720] : [720, 1280]; [canvas.width, canvas.height] = ratio; const ctx = canvas.getContext('2d'); const stream = canvas.captureStream(30); const recorder = new MediaRecorder(stream, { mimeType: 'video/webm;codecs=vp9' }); const chunks = []; recorder.ondataavailable = (event) => event.data.size && chunks.push(event.data); const duration = Math.max(3, Math.min(totalDuration() || 5, 15)); const started = performance.now(); const draw = (now) => { const elapsed = (now - started) / 1000; const progress = Math.min(elapsed / duration, 1); const gradient = ctx.createLinearGradient(0, 0, canvas.width, canvas.height); gradient.addColorStop(0, '#596a7d'); gradient.addColorStop(.45, '#293640'); gradient.addColorStop(1, '#0e1317'); ctx.fillStyle = gradient; ctx.fillRect(0, 0, canvas.width, canvas.height); ctx.fillStyle = 'rgba(201,242,106,.9)'; ctx.font = `${Math.round(canvas.width * .04)}px DM Mono`; ctx.fillText('CENA / 01', canvas.width * .08, canvas.height * .12); ctx.fillStyle = '#eef0ec'; ctx.font = `600 ${Math.round(canvas.width * .075)}px Space Grotesk`; const words = String(scene.title || 'Sua cena').split(' '); words.forEach((word, index) => ctx.fillText(word, canvas.width * .08, canvas.height * (.62 + index * .09))); ctx.fillStyle = 'rgba(255,255,255,.65)'; ctx.font = `${Math.round(canvas.width * .025)}px DM Mono`; ctx.fillText(String(scene.narration || '').slice(0, 70), canvas.width * .08, canvas.height * .9); ctx.fillStyle = 'rgba(201,242,106,.85)'; ctx.fillRect(canvas.width * .08, canvas.height * .95, canvas.width * .84 * progress, 5); if (progress < 1) requestAnimationFrame(draw); else recorder.stop(); }; recorder.onstop = () => { downloadBlob(new Blob(chunks, { type: 'video/webm' }), `${slug(state.name)}.webm`, 'video/webm'); setProgress(100, 'Prévia renderizada no navegador', 'render'); toast('WebM renderizado e baixado. Para MP4, use FFmpeg local.', 'success'); }; recorder.start(); requestAnimationFrame(draw); }
async function pollJob(id) { const timer = setInterval(async () => { try { const job = await (await apiFetch(`/api/jobs/${id}`)).json(); setProgress(job.progress || 0, job.status === 'completed' ? 'Vídeo renderizado' : job.status === 'error' ? job.error : 'Renderizando com FFmpeg…', 'render'); if (job.status === 'completed' || job.status === 'error') clearInterval(timer); if (job.status === 'completed') { $('#renderBtn').onclick = () => window.open(job.output, '_blank'); toast('MP4 pronto para abrir e baixar.', 'success'); } } catch { clearInterval(timer); } }, 900); }

function handleAssets(files) { [...files].forEach((file) => { const url = URL.createObjectURL(file); objectUrls.push(url); state.assets.push({ name: file.name, type: file.type, url }); if (file.type.startsWith('image/') && state.scenes[state.selected]) state.scenes[state.selected].image = url; }); renderScenes(); toast(`${files.length} arquivo(s) adicionado(s) ao projeto.`, 'success'); setStatus('arquivos locais adicionados'); }
function showView(view) { $$('.nav-item').forEach((item) => item.classList.toggle('active', item.dataset.view === view)); $$('.view').forEach((el) => el.classList.toggle('active', el.id === `${view}View`)); if (view === 'library') loadProjects(); }

$('#generateBtn').onclick = generateScript; $('#saveProjectBtn').onclick = saveProject; $('#addSceneBtn').onclick = addScene; $('#downloadSrtBtn').onclick = makeSrt; $('#downloadProjectBtn').onclick = exportProject; $('#renderBtn').onclick = renderVideo; $('#emptyAddBtn')?.addEventListener('click', addScene); $('#assetDrop').onclick = (event) => { if (event.target.closest('button')) $('#assetInput').click(); }; $('#assetInput').onchange = (event) => handleAssets(event.target.files); $('#assetDrop').ondragover = (event) => { event.preventDefault(); $('#assetDrop').style.borderColor = 'var(--lime)'; }; $('#assetDrop').ondragleave = () => $('#assetDrop').style.borderColor = ''; $('#assetDrop').ondrop = (event) => { event.preventDefault(); $('#assetDrop').style.borderColor = ''; handleAssets(event.dataTransfer.files); };
$$('.format-option').forEach((button) => button.onclick = () => { state.format = button.dataset.format; $$('.format-option').forEach((el) => el.classList.toggle('selected', el === button)); updatePreview(); }); $$('.mode').forEach((button) => button.onclick = () => { if (button.dataset.mode === 'ai-video') return toast('Clipes IA ficam opcionais: configure um provedor compatível sem cobrança para habilitar.', 'error'); state.mode = button.dataset.mode; $$('.mode').forEach((el) => el.classList.toggle('selected', el === button)); }); $$('.nav-item').forEach((button) => button.onclick = () => showView(button.dataset.view)); $('#libraryNewBtn').onclick = () => { state.id = null; state.name = 'Sem título'; state.scenes = []; $('#topic').value = ''; renderScenes(); showView('editor'); }; $('#newProjectBtn').onclick = $('#libraryNewBtn').onclick; $('#healthBtn').onclick = async () => { try { const data = await (await apiFetch('/api/health')).json(); toast(`Servidor ativo · Gemini ${data.gemini ? 'configurado' : 'sem chave'} · Supabase ${data.supabase ? 'configurado' : 'local'}.`, data.gemini ? 'success' : ''); } catch { toast('Modo estático: inicie node server/server.mjs para APIs locais.', 'error'); } }; $('#listenVoiceBtn').onclick = async () => { const sample = 'Esta é uma amostra de voz da CENA. A sua ideia começa agora.'; try { const response = await apiFetch('/api/synthesize', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ text: sample, voice: $('#voice').value }) }); if (!response.ok) throw new Error(); const data = await response.json(); const audio = new Audio(URL.createObjectURL(pcmToWav(data.base64))); await audio.play(); toast('Amostra gerada pelo Gemini TTS.', 'success'); } catch { const utterance = new SpeechSynthesisUtterance(sample); utterance.lang = 'pt-BR'; window.speechSynthesis.speak(utterance); toast('Amostra local do navegador reproduzida. Configure o Gemini para a narração final.'); } }; [['voiceVolume','voiceVolumeValue'],['musicVolume','musicVolumeValue']].forEach(([input, output]) => $((`#${input}`)).oninput = (event) => { $(`#${output}`).textContent = `${event.target.value}%`; }); $('#previewBtn').onclick = () => { const scene = currentScene(); if (!scene) return toast('Gere o roteiro para iniciar a prévia.', 'error'); toast(`Cena ${state.selected + 1} em prévia · ${scene.duration}s`, 'success'); };

function pcmToWav(base64, sampleRate = 24000, channels = 1, bits = 16) { const binary = atob(base64); const pcm = new Uint8Array(binary.length); for (let i = 0; i < binary.length; i++) pcm[i] = binary.charCodeAt(i); const header = new ArrayBuffer(44); const view = new DataView(header); const write = (offset, value) => { [...value].forEach((char, index) => view.setUint8(offset + index, char.charCodeAt(0))); }; write(0, 'RIFF'); write(8, 'WAVE'); write(12, 'fmt '); write(36, 'data'); view.setUint32(4, 36 + pcm.length, true); view.setUint32(16, 16, true); view.setUint16(20, 1, true); view.setUint16(22, channels, true); view.setUint32(24, sampleRate, true); view.setUint32(28, sampleRate * channels * bits / 8, true); view.setUint16(32, channels * bits / 8, true); view.setUint16(34, bits, true); view.setUint32(40, pcm.length, true); return new Blob([header, pcm], { type: 'audio/wav' }); }

$('#loginBtn').onclick = () => submitAuth('login'); $('#signupBtn').onclick = () => submitAuth('signup'); $('#continueLocalBtn').onclick = () => { localStorage.setItem('cena-local-only', '1'); $('#authGate').hidden = true; toast('Modo local ativado. Projetos ficam neste navegador.'); }; $('#authPassword').onkeydown = (event) => { if (event.key === 'Enter') submitAuth('login'); };

hydrate({ ...state, scenes: initialScenes, name: 'A luz certa muda tudo' });
bootstrapAuth();


